```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

app.use(helmet());                       // secure HTTP headers
app.use(express.json({ limit: '10kb' })); // bounded body parsing
app.use(rateLimit({ windowMs: 60_000, max: 100 })); // basic DoS protection
```

